/**
 * Guardrails for the pause-classification helpers.
 *
 * Invariant: a reflection row that was generated by the notification pipeline
 * but never engaged with by the user (no outcome, no mood, no breathing)
 * must NOT count toward any metric.
 */
import { describe, it, expect } from 'vitest';

import {
  isCompletedPause,
  isFullRitualPause,
  filterCompleted,
  filterFullRitual,
  pauseTimestamp,
  type EngagedPauseFields,
} from '@/lib/engaged-pause';

// A reflection row as it exists right after a volatility notification is
// generated, before the user taps in.
const ignoredNotification: EngagedPauseFields = {
  breathing_completed: false,
  mood: null,
  mood_after: null,
  outcome: null,
};

// User opened the pause, picked a decision, but skipped breathing / mood shift.
const decisionOnly: EngagedPauseFields = {
  breathing_completed: false,
  mood: 'anxious',
  mood_after: null,
  outcome: 'held',
};

// Full flow.
const fullyEngaged: EngagedPauseFields = {
  breathing_completed: true,
  mood: 'fearful',
  mood_after: 'calm',
  outcome: 'nothing',
};

// Edge: outcome present but empty string (some legacy rows).
const emptyStringOutcome: EngagedPauseFields = {
  breathing_completed: true,
  mood: 'calm',
  mood_after: 'calm',
  outcome: '',
};

describe('isCompletedPause', () => {
  it('returns false for an ignored-notification row', () => {
    expect(isCompletedPause(ignoredNotification)).toBe(false);
  });

  it('returns false for an empty-string outcome', () => {
    expect(isCompletedPause(emptyStringOutcome)).toBe(false);
  });

  it('returns true when an outcome is recorded, even without breathing', () => {
    expect(isCompletedPause(decisionOnly)).toBe(true);
  });

  it('returns true for a fully engaged pause', () => {
    expect(isCompletedPause(fullyEngaged)).toBe(true);
  });
});

describe('isFullRitualPause', () => {
  it('returns false for an ignored-notification row', () => {
    expect(isFullRitualPause(ignoredNotification)).toBe(false);
  });

  it('returns false when only an outcome is recorded (no breathing / no shift)', () => {
    expect(isFullRitualPause(decisionOnly)).toBe(false);
  });

  it('returns true only when every required field is present', () => {
    expect(isFullRitualPause(fullyEngaged)).toBe(true);
  });

  it('rejects rows with empty-string outcome', () => {
    expect(isFullRitualPause(emptyStringOutcome)).toBe(false);
  });
});

describe('filterCompleted / filterFullRitual', () => {
  const rows: EngagedPauseFields[] = [
    ignoredNotification,
    decisionOnly,
    fullyEngaged,
    emptyStringOutcome,
  ];

  it('filterCompleted keeps only rows with a recorded decision', () => {
    const result = filterCompleted(rows);
    expect(result).toEqual([decisionOnly, fullyEngaged]);
  });

  it('filterFullRitual keeps only full-ritual rows', () => {
    const result = filterFullRitual(rows);
    expect(result).toEqual([fullyEngaged]);
  });

  it('ignored notifications never appear in either filter output', () => {
    expect(filterCompleted(rows)).not.toContain(ignoredNotification);
    expect(filterFullRitual(rows)).not.toContain(ignoredNotification);
  });

  it('handles empty input', () => {
    expect(filterCompleted([])).toEqual([]);
    expect(filterFullRitual([])).toEqual([]);
  });
});

describe('pauseTimestamp', () => {
  // Scenario that matters most: a cron row inserted at T0 but engaged with at T1.
  // Bucketing by created_at would land in the wrong day/week.
  const created = '2026-04-15T10:00:00.000Z';
  const engaged = '2026-04-18T22:30:00.000Z';

  it('prefers engaged_at when set', () => {
    const ts = pauseTimestamp({ created_at: created, engaged_at: engaged });
    expect(ts.toISOString()).toBe(engaged);
  });

  it('falls back to created_at when engaged_at is null', () => {
    const ts = pauseTimestamp({ created_at: created, engaged_at: null });
    expect(ts.toISOString()).toBe(created);
  });

  it('falls back to created_at when engaged_at is undefined (legacy row shape)', () => {
    const ts = pauseTimestamp({ created_at: created });
    expect(ts.toISOString()).toBe(created);
  });
});
